    60	/// Format a plugin's live state into a `PluginSchema`.
    61	///
    62	/// This is a *formatter*, not a schema authority — nothing here is indexed. The
    63	/// plugin's `query_current_state()` (its `*State` struct) is the single source
    64	/// of truth; field types are inferred from that state, so the schema can never
    65	/// drift from what the plugin actually reports. To add a field, add it to the
    66	/// plugin state — never hand-write a field definition.
    67	pub(crate) fn schema_from_state(
    68	    name: &str,
    69	    category: &str,
    70	    version: &str,
    71	    description: &str,
    72	    state: &Value,
    73	) -> PluginSchema {
    74	    use simd_json::prelude::*;
    75	
    76	    let mut builder = PluginSchema::builder(name)
    77	        .version(version)
    78	        .category(category)
    79	        .description(description);
    80	
    81	    if let Some(obj) = state.as_object() {
    82	        for (key, value) in obj.iter() {
    83	            builder = builder.field(&key.to_string(), field_from_value(value));
    84	        }
    85	    }
    86	
    87	    builder.example(state.clone()).build()
    88	}
    89	
    90	/// Infer a `FieldSchema` (type + example) from a live state value.
    91	pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
    92	    FieldSchema {
    93	        field_type: infer_field_type(value),
    94	        required: false,
    95	        description: String::new(),
    96	        default: None,
    97	        example: Some(value.clone()),
    98	        constraints: Vec::new(),
    99	        read_only: false,
   100	        read_only_when: None,
   101	    }
   102	}
   103	
   104	/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
   105	pub(crate) fn infer_field_type(value: &Value) -> FieldType {
   106	    use simd_json::prelude::*;
   107	
   108	    if value.is_null() {
   109	        FieldType::Any
   110	    } else if value.as_bool().is_some() {
   111	        FieldType::Boolean
   112	    } else if value.as_i64().is_some() || value.as_u64().is_some() {
   113	        FieldType::Integer
   114	    } else if value.as_f64().is_some() {
   115	        FieldType::Float
   116	    } else if value.as_str().is_some() {
   117	        FieldType::String
   118	    } else if let Some(arr) = value.as_array() {
   119	        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
   120	        FieldType::Array(Box::new(inner))
   121	    } else if let Some(obj) = value.as_object() {
   122	        let fields = obj
   123	            .iter()
   124	            .map(|(k, v)| (k.to_string(), field_from_value(v)))
   125	            .collect();
   126	        FieldType::Object(fields)
   127	    } else {
   128	        FieldType::Any
   129	    }
   130	}
   131	
   132	pub(crate) fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
   133	    FieldSchema {
   134	        field_type: FieldType::Any,
   135	        required,
   136	        description: description.to_string(),
   137	        default,
   138	        example: None,
   139	        constraints: Vec::new(),
   140	        read_only: false,
   141	        read_only_when: None,
   142	    }
   143	}
   144	
   145	pub(crate) fn simple_schema(
   146	    name: &str,
   147	    description: &str,
   148	    dependencies: &[&str],
   149	    fields: Vec<(&str, FieldSchema)>,
   150	) -> PluginSchema {
   151	    let mut builder = PluginSchema::builder(name)
   152	        .version("1.0.0")
   153	        .description(description);
   154	    for dep in dependencies {
   155	        builder = builder.dependency(dep);
   156	    }
   157	    for (field_name, schema) in fields {
   158	        builder = builder.field(field_name, schema);
   159	    }
   160	    builder.build()
   161	}

