use anyhow::{Context, Result};
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::env;

/// Default public Voyage AI endpoint.
const VOYAGE_PUBLIC_URL: &str = "https://api.voyageai.com/v1/embeddings";
/// MongoDB-hosted Voyage AI endpoint (for keys prefixed with `al-`).
const VOYAGE_MONGODB_URL: &str = "https://ai.mongodb.com/v1/embeddings";

/// Voyage AI client for text embeddings
pub struct VoyageClient {
    client: Client,
    api_key: String,
    model: String,
    base_url: String,
}

#[derive(Serialize)]
struct EmbeddingRequest<'a> {
    input: Vec<&'a str>,
    model: &'a str,
    input_type: Option<&'a str>,
}

#[derive(Deserialize)]
struct EmbeddingData {
    embedding: Vec<f32>,
}

#[derive(Deserialize)]
struct EmbeddingResponse {
    data: Vec<EmbeddingData>,
}

impl VoyageClient {
    /// Create a new Voyage client.
    ///
    /// Auto-detects the endpoint: MongoDB-hosted keys (`al-*`) route to
    /// `https://ai.mongodb.com/v1/embeddings`; all others use the public
    /// `https://api.voyageai.com/v1/embeddings` endpoint.
    pub fn new() -> Result<Self> {
        let api_key = env::var("VOYAGE_API_KEY").context("VOYAGE_API_KEY not found")?;
        let model = env::var("VOYAGE_MODEL").unwrap_or_else(|_| "voyage-4".to_string());
        let base_url = voyage_url_for_key(&api_key);

        Ok(Self {
            client: Client::new(),
            api_key,
            model,
            base_url,
        })
    }

    /// Embed text using Voyage API
    pub async fn embed(&self, text: &str, input_type: Option<&str>) -> Result<Vec<f32>> {
        let req = EmbeddingRequest {
            input: vec![text],
            model: &self.model,
            input_type,
        };

        let resp = self
            .client
            .post(&self.base_url)
            .bearer_auth(&self.api_key)
            .json(&req)
            .send()
            .await
            .context("Failed to send Voyage API request")?
            .error_for_status()
            .context("Voyage API returned error status")?
            .json::<EmbeddingResponse>()
            .await
            .context("Failed to parse Voyage API response")?;

        resp.data
            .into_iter()
            .next()
            .map(|d| d.embedding)
            .context("Voyage API returned no embeddings")
    }
}

/// Determine the correct Voyage endpoint for a given API key.
fn voyage_url_for_key(key: &str) -> String {
    let trimmed = key.trim();
    if trimmed.starts_with("al-") {
        VOYAGE_MONGODB_URL.to_string()
    } else {
        VOYAGE_PUBLIC_URL.to_string()
    }
}
///
/// Override the URL with `COGNITIVE_MCP_QDRANT_URL`.
pub fn qdrant_client_from_env() -> Result<Qdrant> {
    let url = std::env::var("COGNITIVE_MCP_QDRANT_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:6334".into());
    Qdrant::from_url(&url)
        .build()
        .context("Failed to build Qdrant client")
}

/// Load the Voyage API key from a secret file when env vars are unset.
///
/// Defaults to `~/.ssh/mongo-voyage`; override with the
/// `COGNITIVE_MCP_VOYAGE_KEY_FILE` env var. The first non-empty line is used
/// (so a key file with a trailing newline or comment lines works).
fn voyage_key_from_file() -> Option<String> {
    let path = std::env::var("COGNITIVE_MCP_VOYAGE_KEY_FILE")
        .ok()
        .map(std::path::PathBuf::from)
        .or_else(|| std::env::var_os("HOME").map(|h| Path::new(&h).join(".ssh/mongo-voyage")))?;

    let contents = std::fs::read_to_string(&path).ok()?;
    // The creds file may contain multiple credential types (Atlas service
    // account ID/secret, plus a Voyage API key).  We must skip service
    // account lines and pick the actual API key.
    let key = contents
        .lines()
        .map(str::trim)
        .find(|l| {
            !l.is_empty()
                && !l.starts_with('#')
                // skip Atlas service-account tokens
                && !l.starts_with("mdb_sa_id_")
                && !l.starts_with("mdb_sa_sk_")
                // line should look like a Voyage key (MongoDB-hosted or public)
                && (l.starts_with("al-") || l.starts_with("pa-"))
        })?
        .to_string();

    if key.is_empty() {
        None
    } else {
        info!(path = %path.display(), "Loaded Voyage API key from file");
        Some(key)
    }
}

